80,"on":["test.completed"],"if":"test.valid && !p.approved_P10","then":[{"set":"s.wpuA","to":"roundLoad(s.wpuC + 1 * s.kgPerRep, 'belt', 'nearest')"},{"set":"s.wpuB","to":"roundLoad(s.wpuC + 3 * s.kgPerRep, 'belt', 'nearest')"}],"explain":{"en":"Working loads re-derived from the measured anchor: A = anchor + 1 rep, B = anchor + 3 reps ({kgPerRep} kg per rep)."},"source":"artifact section 05 / section 10 ('elke testdag ... werkgewichten opnieuw berekend')"},{"id":"data.test.loads.curve","tag":"P","proposal":"P10","stage":"data","prio":80,"on":["test.completed"],"if":"test.valid && p.approved_P10 && defined(t.wpu_3rm_added)","let":[{"name":"T1","expr":"t.bw + t.wpu_e1rm_added"},{"name":"jump","expr":"p.maxRecalcJumpKg"},{"name":"c","expr":"roundLoad(clamp(s.anchorFraction * T1 - bw, s.wpuC - jump, s.wpuC + jump), 'belt', 'nearest')"},{"name":"slope","expr":"kgPerRepAt(bw + c, p.anchorReps, userK('weighted_pullup'))"}],"then":[{"set":"s.wpuC","to":"c"},{"set":"s.kgPerRep","to":"slope"},{"set":"s.wpuA","to":"roundLoad(clamp(c + 1 * slope, s.wpuA - jump, s.wpuA + jump), 'belt', 'nearest')"},{"set":"s.wpuB","to":"roundLoad(clamp(c + 3 * slope, s.wpuB - jump, s.wpuB + jump), 'belt', 'nearest')"}],"explain":{"en":"Anchor = {anchorFraction} x {T1} kg - BW = {c} kg; {slope} kg per rep on your curve; A and B follow, each change capped at 5 kg."},"source":"proposal P10"},{"id":"data.test.neg","tag":"A","supersededBy":"P09","stage":"data","prio":78,"on":["test.completed"],"if":"test.valid && !p.approved_P09 && defined(t.wpu_3rm_added)","let":[{"name":"n","expr":"roundLoad(p.negFraction * (t.bw + t.wpu_e1rm_added) - bw, 'belt', 'down')"}],"then":[{"set":"s.negB","to":"n"},{"set":"s.negReset","to":"roundLoad(n - p.negResetStep, 'belt', 'down')"}],"explain":{"en":"Negatives = 105 % of the gate 1RM, rounded down to a loadable weight."},"source":"artifact section 05"},{"id":"data.test.neg.keep","tag":"P","proposal":"P09","stage":"data","prio":78,"on":["test.completed"],"if":"test.valid && p.approved_P09 && defined(t.wpu_3rm_added)","let":[{"name":"n","expr":"roundLoad(p.negFraction * (t.bw + t.wpu_e1rm_added) - bw, 'belt', 'down')"},{"name":"jump","expr":"p.maxRecalcJumpKg"},{"name":"v","expr":"validInBlock('neg') > 0 ? max(s.negB, min(n, s.negB + jump)) : clamp(n, s.negB - jump, s.negB + jump)"}],"then":[{"set":"s.negB","to":"roundLoad(v, 'belt', 'down')"},{"set":"s.negReset","to":"roundLoad(v - p.negResetStep, 'belt', 'down')"}],"explain":{"en":"Negatives logged this block keep their own progression; the recalculation may raise them but never lowers them."},"source":"proposal P09"},{"id":"data.test.pins","tag":"P","proposal":"P11","stage":"data","prio":76,"on":["test.completed"],"if":"test.valid && p.approved_P11 && defined(t.oa_least_assist_pin)","let":[{"name":"weak","expr":"max(t.oa_least_assist_pin)"}],"then":[{"set":"s.pinA","to":"roundPin(weak + p.pinOffsetA, 'up')"},{"set":"s.pinC","to":"roundPin(weak + p.pinOffsetA + p.pinOffsetC, 'up')"},{"set":"s.pinHold90","to":"roundPin(max(0lb, weak + p.pinOffsetA + p.pinOffsetHold90), 'up')"},{"set":"s.aFailStreak","to":"0"}],"explain":{"en":"Weaker arm needed {weak} lb: A {pinA} lb, C {pinC} lb, 90-degree hold {pinHold90} lb."},"source":"proposal P11"},{"id":"data.test.hangTarget","tag":"P","proposal":"P06","stage":"data","prio":74,"on":["test.completed"],"if":"test.valid && p.approved_P06 && defined(t.oa_hang_s)","then":[{"set":"s.oaHangS","to":"clamp(floor(p.hangTargetFraction * min(t.oa_hang_s)), p.hangTargetMin, min(p.hangTargetMax, s.oaHangS + p.hangTargetMaxStep))"}],"explain":{"en":"C hang target = 67 % of your weaker fresh hang ({weaker} s), within 10-30 s."},"source":"proposal P06; Todoist C ('reviewed on test day')"},{"id":"data.test.deadStart","tag":"A","stage":"data","prio":72,"on":["test.completed"],"if":"test.valid && !s.deadStartUnlocked && defined(t.oa_hang_s) && min(t.oa_hang_s) > p.deadStartUnlockHangS","then":[{"set":"s.deadStartUnlocked","to":"true"},{"notify":"info","msg":"dead_start_unlocked","once":"ever"}],"explain":{"en":"Your fresh one-arm hang is above 15 s on a test day: starts from a dead hang may return (needs a definition update)."},"source":"artifact section 06 / Todoist A"},{"id":"data.pinA.report","tag":"A","stage":"data","prio":50,"on":["session.completed"],"if":"sess.slot == 'A' && mode == 'normal' && !s.pinAReportShown && valid('oaa') && last(ex.oaa.pin) <= p.pinAReportLb && count(ex.oaa.reps) >= ex.oaa.plannedRows && all(ex.oaa.reps >= ex.oaa.targetReps)","then":[{"set":"s.pinAReportShown","to":"true"},{"notify":"info","msg":"pin_report_baseline","once":"ever"}],"explain":{"en":"5 x 3 per arm at 35 lb or less: the 30-08 baseline underestimated your pulling strength (noted in your history)."},"source":"Todoist A ('Let op bij 35 lbs')"},{"id":"struct.test.postpone","tag":"A","stage":"structural","prio":40,"on":["test.due"],"if":"s.needsCleanSession","then":[{"setMode":"test_pending"},{"postponeTest":"firstTestWeekdayAfterCleanSession"},{"notify":"info","msg":"test_postponed"}],"explain":{"en":"No clean session since the interruption: today becomes session B (deload form) and the test moves to the first Sunday after a clean session."},"source":"artifact section 01 'Volgende meting' / section 10; C36"},{"id":"struct.cleanSession","tag":"A","uses":["P25"],"stage":"structural","prio":38,"on":["session.completed"],"if":"sess.slot in ['A', 'B', 'C'] && mode != 'injury' && !sess.painReported && (p.approved_P25 ? sess.completionRatio >= p.cleanSessionRatio : true)","then":[{"set":"s.needsCleanSession","to":"false"}],"explain":{"en":"A normal session without complaints: the next test day can go ahead."},"source":"artifact section 01 / section 10 ('een gewone sessie zonder klachten')"},{"id":"struct.test.done","tag":"A","stage":"structural","prio":30,"on":["test.completed"],"if":"test.valid","then":[{"set":"s.blockEndPending","to":"true"},{"notify":"info","msg":"test_recorded"}],"explain":{"en":"Valid test: the next block starts on Monday with the recalculated loads."},"source":"artifact sections 04, 07, 10"},{"id":"struct.stall","tag":"A","uses":["P04"],"stage":"structural","prio":25,"on":["test.completed"],"if":"test.valid && defined(pt.bw)","then":[{"if":"d.testProgress","do":[{"set":"s.noProgressTests","to":"0"},{"set":"s.stallStage","to":"0"}],"else":[{"set":"s.noProgressTests","to":"s.noProgressTests + 1"},{"if":"s.stallStage == 0 && s.noProgressTests + 1 >= p.stallTestsStage1","do":[{"set":"s.stallStage","to":"1"},{"notify":"warn","msg":"stall_sleep_food"}],"else":[{"if":"s.stallStage == 1 && s.noProgressTests + 1 >= p.stallTestsStage2","do":[{"set":"s.stallStage","to":"2"},{"set":"s.bVariant","to":"'ladder123'"},{"set":"s.extraDeloadPending","to":"true"},{"notify":"warn","msg":"stall_ladders"}]}]}]}],"explain":{"en":"Two tests without progress: check sleep and food (not a signal to train harder). Still no progress: B switches to 1-2-3 ladders and an extra deload week is inserted."},"source":"artifact section 05 / section 10"},{"id":"struct.stall.revert","tag":"P","proposal":"P24","stage":"structural","prio":24,"on":["test.completed"],"if":"test.valid && p.approved_P24 && s.bVariant == 'ladder123' && defined(pt.bw) && d.testProgress","then":[{"set":"s.bVariant","to":"'6x2'"}],"explain":{"en":"The test showed progress again: B returns to 6 x 2."},"source":"proposal P24"},{"id":"struct.phase.gate","tag":"A","stage":"structural","prio":20,"on":["test.completed","attempt.logged"],"if":"phaseGatePasses(phase)","then":[{"advancePhase":true},{"notify":"celebrate","msg":"phase_up"}],"explain":{"en":"All gate criteria met: next phase (or challenge complete)."},"source":"artifact section 03 / section 10 ('ongeacht in welke week je zit')"},{"id":"struct.block.rollover","tag":"A","stage":"structural","prio":15,"on":["week.closed"],"if":"s.blockEndPending","then":[{"startNewBlock":{"firstWeekMode":"s.extraDeloadPending ? 'extra_deload' : 'normal'"}},{"set":"s.blockEndPending","to":"false"},{"set":"s.extraDeloadPending","to":"false"}],"explain":{"en":"New block: week 1 (or an extra deload week first)."},"source":"artifact sections 04 and 10"},{"id":"struct.week.close","tag":"A","uses":["P02"],"stage":"structural","prio":14,"on":["week.closed"],"if":"!s.blockEndPending && mode != 'injury'","then":[{"if":"mode == 'extra_deload'","do":[{"advanceWeek":true},{"setMode":"normal"}],"else":[{"if":"mode in ['deload', 'test_pending']","do":[{"repeatWeek":true},{"setMode":"test_pending"},{"notify":"info","msg":"test_still_pending"}],"else":[{"if":"d.weekCounts","do":[{"advanceWeek":true}],"else":[{"repeatWeek":true},{"set":"s.needsCleanSession","to":"true"},{"notify":"info","msg":"missed_week_no_makeup"}]}]}]}],"explain":{"en":"Week closed: advance, or repeat with the same loads (no make-up), or keep waiting for the test."},"source":"artifact section 10 ('niets inhalen ... dezelfde gewichten')"},{"id":"struct.deload.enter","tag":"P","proposal":"P07","stage":"structural","prio":12,"on":["week.started"],"if":"p.approved_P07 && mode == 'normal' && block.week == p.blockWeeks","then":[{"setMode":"deload"},{"scheduleTest":"testWeekday"}],"explain":{"en":"Week 5 of the block: deload (half sets, same loads), test on Sunday."},"source":"artifact section 04; F9"},{"id":"struct.deload.enter.fixed","tag":"A","supersededBy":"P07","stage":"structural","prio":12,"on":["week.started"],"if":"!p.approved_P07 && mode == 'normal' && isoWeekOf(nextFixedTestDate(today)) == week.iso","then":[{"setMode":"deload"},{"scheduleTest":"fixedDate"}],"explain":{"en":"This week contains a test date from the fixed list: deload, test on Sunday."},"source":"artifact section 07 table"},{"id":"struct.resume.interrupt","tag":"A","supersededBy":"P15","stage":"structural","prio":11,"on":["resume"],"if":"!p.approved_P15 && event.gapDays >= 1d","then":[{"set":"s.needsCleanSession","to":"true"},{"notify":"info","msg":"resume_same_week"}],"explain":{"en":"Back after an interruption: you continue in the same week with the same loads; the next test waits for a normal session without complaints."},"source":"artifact section 10 ('Bij een gemiste week ... Na een onderbreking schuift een testdag door')"},{"id":"struct.resume.repeat","tag":"P","proposal":"P15","stage":"structural","prio":11,"on":["resume"],"if":"p.approved_P15 && event.gapDays >= p.pauseRepeatDays && event.gapDays < p.pauseRestartDays","then":[{"set":"s.needsCleanSession","to":"true"},{"notify":"info","msg":"resume_repeat"}],"explain":{"en":"Paused {gapDays} days: this week repeats with the same loads and the next test waits for a clean session."},"source":"proposal P15"},{"id":"struct.resume.restart","tag":"P","proposal":"P15","stage":"structural","prio":11,"on":["resume"],"if":"p.approved_P15 && event.gapDays >= p.pauseRestartDays","then":[{"restoreSnapshot":"block.index"},{"restartBlock":true},{"set":"s.needsCleanSession","to":"true"},{"set":"s.blockEndPending","to":"false"},{"notify":"info","msg":"resume_restart"}],"explain":{"en":"Paused {gapDays} days: the block restarts at week 1 with the loads it started with."},"source":"proposal P15"},{"id":"prog.gripSlip.lock","tag":"A","stage":"progression","prio":60,"on":["session.completed"],"if":"sess.slot in ['A', 'B', 'C'] && any(ex.wpu.grip_slip_before_last)","then":[{"lock":["s.wpuA","s.wpuB","s.wpuC"],"kind":"noIncrease"},{"notify":"info","msg":"grip_not_strength"}],"explain":{"en":"The hand slipped before the last rep: no weight added this time (grip, not strength)."},"source":"artifact section 05 / Todoist A and B"},{"id":"prog.B.wpu","tag":"A","stage":"progression","prio":50,"on":["session.completed"],"if":"sess.slot == 'B' && mode == 'normal' && s.bVariant == '6x2' && valid('wpu') && count(ex.wpu.reps) >= ex.wpu.plannedRows && all(ex.wpu.reps >= ex.wpu.targetReps) && min(ex.wpu.rir) >= p.bMinRir","then":[{"adjust":"s.wpuB","by":"p.bStepKg","round":{"profile":"belt","mode":"nearest"}}],"explain":{"en":"All 6 x 2 with at least 2 reps in reserve: +2.5 kg next week."},"source":"artifact section 05 / Todoist B"},{"id":"prog.B.neg.up","tag":"A","$def$)
on conflict (part) do update set txt = excluded.txt;
